    long j = parse_expr(vm,L);
    long amt = parse_expr(vm,L);
    if (i < 0) i = 0;
    if (j < 0) j = 0;
    if (i >= CUBALC_CELL_N) i = CUBALC_CELL_N - 1;
    if (j >= CUBALC_CELL_N) j = CUBALC_CELL_N - 1;
