    if (nb > CUBALC_ATOM_BITS) nb = CUBALC_ATOM_BITS;
    int nn = na > nb ? na : nb;
    if (nn < 1) nn = CUBALC_ATOM_BITS;
    long d = 0;
    for (int k=0;k<nn;k++){
      int ba = cubalc_matrix_get(ma, k) ? 1 : 0;
      int bb = cubalc_matrix_get(mb, k) ? 1 : 0;
      if (ba && bb) d++;
    }
    var_set_num(vm,"LAST_N",d); vm->last_n=d;
