    int is=find_cube(vm,srcid); if (is<0){ place_cube(vm,srcid,srcid,1); is=find_cube(vm,srcid); }
    if (id<0||is<0){ fail(vm,"COPYRANGE cube missing"); return -1; }
    cubalc_matrix *md = &vm->ch.cubes[id].atom.matrix;
