    cubalc_matrix *m = &vm->ch.cubes[ix].atom.matrix;
    int n = m->n > 0 ? m->n : CUBALC_ATOM_BITS;
    if (n > CUBALC_ATOM_BITS) n = CUBALC_ATOM_BITS;
    /* pack bits 0..min(63,n-1) into unsigned 64-bit value (signed long storage) */
    int w = n < 64 ? n : 64;
